if (!defined('CLI_SCRIPT')) { define('CLI_SCRIPT', true); }
require('/www/moodle/config.php');
require_once($CFG->dirroot . '/lib/questionlib.php');
require_once($CFG->dirroot . '/question/format/xml/format.php');
require_once($CFG->dirroot . '/mod/quiz/lib.php');
require_once($CFG->dirroot . '/mod/quiz/locallib.php');
try {
    global $DB, $USER;
    $USER = get_admin();

    $course = $DB->get_record('course', ['shortname' => 'GUESSIT01']);
    if (!$course) {
        throw new \RuntimeException("Course 'GUESSIT01' was not found.");
    }

    $questionbanks = $DB->get_records('qbank', ['course' => $course->id]);
    if (count($questionbanks) !== 1) {
        throw new \RuntimeException("Expected one question bank for course 'GUESSIT01'; found " . count($questionbanks) . '.');
    }
    $questionbank = reset($questionbanks);
    $questionbankcm = get_coursemodule_from_instance('qbank', $questionbank->id, $course->id);
    if (!$questionbankcm) {
        throw new \RuntimeException("The course-module record for the 'GUESSIT01' question bank was not found.");
    }
    $questionbankcontext = context_module::instance($questionbankcm->id);
    $category = question_get_default_category($questionbankcontext->id, true);
    if (!$category) {
        throw new \RuntimeException("The default question category for course 'GUESSIT01' was not found or created.");
    }

    $findquestion = static function () use ($DB, $category) {
        $sql = "SELECT q.*
                  FROM {question} q
                  JOIN {question_versions} qv ON qv.questionid = q.id
                  JOIN {question_bank_entries} qbe ON qbe.id = qv.questionbankentryid
                 WHERE qbe.questioncategoryid = :categoryid
                   AND q.qtype = :qtype
                   AND q.name = :name
              ORDER BY qv.version DESC, q.id DESC";
        $questions = $DB->get_records_sql($sql, [
            'categoryid' => $category->id,
            'qtype' => 'guessit',
            'name' => 'guessit-001',
        ], 0, 2);
        if (count($questions) > 1) {
            throw new \RuntimeException("More than one 'guessit-001' Guess It question exists in the target category.");
        }
        return $questions ? reset($questions) : false;
    };

    $question = $findquestion();
    if (!$question) {
        $xml = <<<'GUESSITXML'
<?xml version="1.0" encoding="UTF-8"?>
<quiz>
  <question type="guessit">
    <name>
      <text>guessit-001</text>
    </name>
    <questiontext format="html">
      <text><![CDATA[<p>Guess this English proverb.</p>]]></text>
    </questiontext>
    <generalfeedback format="html">
      <text><![CDATA[<p>Well-done!</p>]]></text>
    </generalfeedback>
    <defaultgrade>6</defaultgrade>
    <penalty>0</penalty>
    <hidden>0</hidden>
    <idnumber></idnumber>
    <guessitgaps>Too many cooks spoil the broth.</guessitgaps>
    <nbtriesbeforehelp>6</nbtriesbeforehelp>
    <nbmaxtrieswordle>0</nbmaxtrieswordle>
    <wordle>0</wordle>
  </question>
</quiz>
GUESSITXML;
        $tmpdir = make_request_directory();
        $tmpfile = $tmpdir . '/guessit.xml';
        if (file_put_contents($tmpfile, $xml) === false) {
            throw new \RuntimeException('Could not write the temporary Guess It question import file.');
        }

        $qformat = new qformat_xml();
        $qformat->setCategory($category);
        $qformat->setContexts([$questionbankcontext]);
        $qformat->setCourse($course);
        $qformat->setFilename($tmpfile);
        $qformat->setMatchgrades('error');
        $qformat->setCatfromfile(false);
        $qformat->setContextfromfile(false);
        $qformat->setStoponerror(true);
        $qformat->set_display_progress(false);
        ob_start();
        try {
            $imported = $qformat->importpreprocess()
                && $qformat->importprocess()
                && $qformat->importpostprocess();
        } finally {
            ob_end_clean();
        }
        if (!$imported || count($qformat->questionids) !== 1) {
            throw new \RuntimeException('Moodle XML import did not create exactly one Guess It question.');
        }
        $question = $findquestion();
        if (!$question || (int) $question->id !== (int) reset($qformat->questionids)) {
            throw new \RuntimeException("The imported 'guessit-001' question could not be retrieved from its category.");
        }
    }

    $quizzes = $DB->get_records('quiz', ['course' => $course->id, 'name' => 'Testing Guess It!']);
    if (count($quizzes) !== 1) {
        throw new \RuntimeException("Expected one quiz named 'Testing Guess It!' in course 'GUESSIT01'; found " . count($quizzes) . '.');
    }
    $quiz = reset($quizzes);
    $quizcm = get_coursemodule_from_instance('quiz', $quiz->id, $course->id);
    if (!$quizcm) {
        throw new \RuntimeException("The course-module record for quiz 'Testing Guess It!' was not found.");
    }
    $quiz->cmid = $quizcm->id;
    $quiz->cmidnumber = $quizcm->idnumber ?? '';

    if ((int) $quiz->cmid !== 2) {
        throw new \RuntimeException("Quiz 'Testing Guess It!' must have course-module ID 2 for the configured landing page; found {$quiz->cmid}.");
    }

    $questionbankentry = get_question_bank_entry($question->id);
    $assignedcount = $DB->count_records_sql(
        "SELECT COUNT(1)
           FROM {quiz_slots} slot
           JOIN {question_references} qr ON qr.itemid = slot.id
          WHERE slot.quizid = :quizid
            AND qr.component = :component
            AND qr.questionarea = :questionarea
            AND qr.questionbankentryid = :questionbankentryid",
        [
            'quizid' => $quiz->id,
            'component' => 'mod_quiz',
            'questionarea' => 'slot',
            'questionbankentryid' => $questionbankentry->id,
        ]
    );
    if ($assignedcount > 1) {
        throw new \RuntimeException("The 'guessit-001' question is assigned to the quiz more than once.");
    }
    if ($assignedcount === 0) {
        quiz_add_quiz_question($question->id, $quiz, 0, 6);
    }

    $assignedcount = $DB->count_records_sql(
        "SELECT COUNT(1)
           FROM {quiz_slots} slot
           JOIN {question_references} qr ON qr.itemid = slot.id
          WHERE slot.quizid = :quizid
            AND qr.component = :component
            AND qr.questionarea = :questionarea
            AND qr.questionbankentryid = :questionbankentryid",
        [
            'quizid' => $quiz->id,
            'component' => 'mod_quiz',
            'questionarea' => 'slot',
            'questionbankentryid' => $questionbankentry->id,
        ]
    );
    if ($assignedcount !== 1) {
        throw new \RuntimeException("The 'guessit-001' question could not be assigned to the quiz.");
    }

    $quizsettings = \mod_quiz\quiz_settings::create($quiz->id);
    $quizsettings->get_grade_calculator()->recompute_quiz_sumgrades();
    $quiz = $DB->get_record('quiz', ['id' => $quiz->id]);
    if (!$quiz || (float) $quiz->sumgrades !== 6.0 || (float) $quiz->grade !== 6.0) {
        throw new \RuntimeException("Quiz grade and sum-of-grades must both equal 6.");
    }
    $quiz->cmid = $quizcm->id;
    $quiz->cmidnumber = $quizcm->idnumber ?? '';
    quiz_update_grades($quiz);

    echo "Provisioned quiz 'Testing Guess It!' with question 'guessit-001' at cmid={$quiz->cmid}.\n";
} catch (\Throwable $e) {
    fwrite(STDERR, 'Guess It quiz provisioning failed: ' . $e->getMessage() . "\n");
}
